'use client'

import { useState, useEffect } from 'react'
import { ArrowLeft, MapPin, AlertCircle, Loader, CheckCircle, ChevronDown, ChevronUp } from 'lucide-react'
import Link from 'next/link'

interface SafeLocation {
  name: string
  type: 'police' | 'hospital' | 'shelter' | 'public'
  latitude: number
  longitude: number
}

// Haversine formula to calculate distance between two coordinates
const calculateDistance = (lat1: number, lon1: number, lat2: number, lon2: number): number => {
  const R = 6371
  const dLat = (lat2 - lat1) * (Math.PI / 180)
  const dLon = (lon2 - lon1) * (Math.PI / 180)
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(lat1 * (Math.PI / 180)) * Math.cos(lat2 * (Math.PI / 180)) * Math.sin(dLon / 2) * Math.sin(dLon / 2)
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))
  return R * c
}

// Generate step-by-step directions
const generateDirections = (startLat: number, startLon: number, endLat: number, endLon: number, destName: string) => {
  const latDiff = endLat - startLat
  const lonDiff = endLon - startLon
  const distance = calculateDistance(startLat, startLon, endLat, endLon)
  
  const directions = []
  
  // First direction
  if (Math.abs(latDiff) > Math.abs(lonDiff)) {
    directions.push(latDiff > 0 ? 'Head North' : 'Head South')
    if (lonDiff > 0.001) directions.push('Slightly Northeast')
    if (lonDiff < -0.001) directions.push('Slightly Northwest')
  } else {
    directions.push(lonDiff > 0 ? 'Head East' : 'Head West')
    if (latDiff > 0.001) directions.push('Slightly North')
    if (latDiff < -0.001) directions.push('Slightly South')
  }
  
  directions.push(`Walk for approximately ${(distance * 1.2).toFixed(1)}km`)
  directions.push('Follow street signs and landmarks')
  directions.push(`Arrive at ${destName}`)
  directions.push('Alert local authorities if safe')
  
  return directions
}

export default function SafePathPage() {
  const [location, setLocation] = useState<{ latitude: number; longitude: number } | null>(null)
  const [mapLoading, setMapLoading] = useState(true)
  const [safeLocations, setSafeLocations] = useState<SafeLocation[]>([])
  const [selectedRoute, setSelectedRoute] = useState<SafeLocation | null>(null)
  const [expandedDirections, setExpandedDirections] = useState(false)

  useEffect(() => {
    const detectLocation = () => {
      if (!navigator.geolocation) {
        setMapLoading(false)
        return
      }

      navigator.geolocation.getCurrentPosition(
        (position) => {
          const coords = {
            latitude: position.coords.latitude,
            longitude: position.coords.longitude
          }
          setLocation(coords)
          generateSafeLocations(coords)
          setMapLoading(false)
        },
        () => {
          setMapLoading(false)
        }
      )
    }

    detectLocation()
  }, [])

  const generateSafeLocations = (currentLocation: { latitude: number; longitude: number }) => {
    const safeSpots = [
      {
        name: 'Police Station',
        type: 'police' as const,
        latitude: currentLocation.latitude + 0.005,
        longitude: currentLocation.longitude + 0.004
      },
      {
        name: 'Hospital',
        type: 'hospital' as const,
        latitude: currentLocation.latitude - 0.006,
        longitude: currentLocation.longitude + 0.003
      },
      {
        name: 'Shopping Mall',
        type: 'public' as const,
        latitude: currentLocation.latitude + 0.008,
        longitude: currentLocation.longitude - 0.005
      },
      {
        name: 'Women\'s Shelter',
        type: 'shelter' as const,
        latitude: currentLocation.latitude - 0.004,
        longitude: currentLocation.longitude - 0.006
      },
      {
        name: 'Fire Station',
        type: 'police' as const,
        latitude: currentLocation.latitude + 0.003,
        longitude: currentLocation.longitude - 0.007
      }
    ]

    setSafeLocations(safeSpots)
  }

  const getMapUrl = () => {
    if (!location) return ''
    const markers = safeLocations
      .map(loc => `marker/${loc.latitude},${loc.longitude}`)
      .join('/')
    const baseMarker = `marker/${location.latitude},${location.longitude}`
    return `https://www.openstreetmap.org/export/embed.html?bbox=${location.longitude - 0.05},${location.latitude - 0.05},${location.longitude + 0.05},${location.latitude + 0.05}&layer=mapnik&marker=${location.latitude},${location.longitude}`
  }

  return (
    <main className="min-h-screen bg-background flex flex-col">
      <Link href="/" className="fixed top-20 left-4 sm:left-8 p-2 hover:bg-dark-tertiary rounded-lg transition-colors z-10">
        <ArrowLeft className="w-6 h-6" />
      </Link>

      <div className="max-w-6xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-12 pt-24 flex flex-col flex-1">
        <div className="mb-8">
          <h1 className="text-4xl font-bold mb-2">Safe Path Assistant</h1>
          <p className="text-muted">View nearby safe locations and get step-by-step directions</p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 flex-1">
          {/* Left: Map */}
          <div className="lg:col-span-2">
            <div className="card overflow-hidden h-96 lg:h-full bg-dark-secondary">
              {mapLoading ? (
                <div className="w-full h-full flex items-center justify-center">
                  <div className="text-center">
                    <Loader className="w-6 h-6 text-brand animate-spin mx-auto mb-2" />
                    <p className="text-xs text-muted">Detecting your location...</p>
                  </div>
                </div>
              ) : !location ? (
                <div className="w-full h-full flex items-center justify-center">
                  <div className="text-center px-4">
                    <AlertCircle className="w-6 h-6 text-brand mx-auto mb-2" />
                    <p className="text-xs text-muted">Enable location access to view map</p>
                  </div>
                </div>
              ) : (
                <iframe
                  src={getMapUrl()}
                  width="100%"
                  height="100%"
                  style={{ border: 0 }}
                  allowFullScreen
                  loading="lazy"
                  referrerPolicy="no-referrer-when-downgrade"
                  className="w-full h-full"
                />
              )}
            </div>
          </div>

          {/* Right: Safe Locations List */}
          <div className="flex flex-col gap-4">
            <div className="card flex-1 overflow-hidden flex flex-col">
              <h2 className="font-semibold mb-4 p-6 pb-0">Nearby Safe Locations</h2>
              <div className="space-y-2 overflow-y-auto flex-1 p-6 pt-2">
                {mapLoading ? (
                  <div className="flex items-center justify-center py-8">
                    <Loader className="w-5 h-5 animate-spin text-brand mr-2" />
                    <span className="text-muted text-sm">Loading...</span>
                  </div>
                ) : safeLocations.length === 0 ? (
                  <div className="flex items-center justify-center py-8">
                    <span className="text-muted text-sm">No locations found</span>
                  </div>
                ) : (
                  safeLocations.map((safeLocation, index) => (
                    <div key={index} className="space-y-2">
                      <button
                        onClick={() => {
                          setSelectedRoute(safeLocation)
                          setExpandedDirections(true)
                        }}
                        className={`w-full text-left p-4 rounded-xl border-2 transition-all duration-200 ${
                          selectedRoute?.name === safeLocation.name
                            ? 'bg-brand-light border-brand shadow-md'
                            : 'border-border hover:border-brand-light hover:bg-dark-secondary'
                        }`}
                      >
                        <div className="flex items-start gap-3">
                          <div className={`w-3 h-3 rounded-full mt-1.5 flex-shrink-0 ${
                            safeLocation.type === 'police' ? 'bg-blue-500' :
                            safeLocation.type === 'hospital' ? 'bg-red-500' :
                            safeLocation.type === 'public' ? 'bg-yellow-500' :
                            'bg-green-500'
                          }`} />
                          <div className="flex-1 min-w-0">
                            <p className="font-semibold text-sm">{safeLocation.name}</p>
                            <p className="text-xs text-muted mt-1">{safeLocation.type}</p>
                          </div>
                          {selectedRoute?.name === safeLocation.name && (
                            <CheckCircle className="w-5 h-5 text-brand flex-shrink-0" />
                          )}
                        </div>
                      </button>

                      {selectedRoute?.name === safeLocation.name && expandedDirections && location && (
                        <div className="bg-dark-secondary border-2 border-brand-light rounded-xl p-4 ml-2">
                          <button
                            onClick={() => setExpandedDirections(!expandedDirections)}
                            className="flex items-center justify-between w-full mb-3"
                          >
                            <h3 className="font-semibold text-sm">Step-by-Step Directions</h3>
                            {expandedDirections ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
                          </button>
                          <div className="space-y-2">
                            {generateDirections(location.latitude, location.longitude, safeLocation.latitude, safeLocation.longitude, safeLocation.name).map((direction, idx) => (
                              <div key={idx} className="flex gap-2 items-start text-xs">
                                <div className="w-5 h-5 rounded-full bg-brand/20 border border-brand text-brand flex items-center justify-center text-xs font-bold flex-shrink-0">
                                  {idx + 1}
                                </div>
                                <p className="text-muted pt-0.5">{direction}</p>
                              </div>
                            ))}
                          </div>
                        </div>
                      )}
                    </div>
                  ))
                )}
              </div>
            </div>

            {/* Safety Tips */}
            <div className="card bg-dark-secondary border-brand-light border-2">
              <div className="flex gap-2 mb-3">
                <AlertCircle className="w-5 h-5 text-brand flex-shrink-0" />
                <h3 className="font-semibold text-sm">Safety Tips</h3>
              </div>
              <ul className="space-y-2 text-xs text-muted">
                <li>✓ Keep your phone charged</li>
                <li>✓ Share your location with someone</li>
                <li>✓ Stay on well-lit streets</li>
                <li>✓ Walk with purpose</li>
                <li>✓ Trust your instincts</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    </main>
  )
}
